/**
 * Shape animation (<p:timing>) read/write — the engine layer behind PowerPoint's
 * "Animations" tab.
 *
 * Model: a slide's animations are an ordered list SlideAnimation[], each item =
 * target shape (spid) + effect + trigger (onClick/withPrev/afterPrev) +
 * duration/delay. On write-back the whole <p:timing> is rebuilt (tmRoot → mainSeq
 * → one par per "click group" → one par per effect), structurally identical to
 * the skeleton PowerPoint itself generates, so the saved pptx plays directly in
 * PowerPoint.
 *
 * spid targeting: OOXML animations use <p:spTgt spid="N"/> pointing at the shape's
 * <p:cNvPr id="N">. The editor's element ids are transient (they change on
 * reparse), so elementSpid() extracts the stable cNvPr id from the element's raw
 * bytes for the mapping.
 *
 * Read-back: parsing our own generated skeleton round-trips losslessly; complex
 * timings generated by PowerPoint get a best-effort downgrade (unmodeled presetIDs
 * map to a similar effect in the same class).
 */
import type { Slide, SlideElement } from './types';
export type AnimEffectKind = 'appear' | 'fade' | 'flyIn' | 'wipe' | 'wipeDown' | 'splitIn' | 'bounce' | 'flipIn' | 'zoom' | 'pulse' | 'spin' | 'grow' | 'teeter' | 'disappear' | 'fadeOut' | 'flyOut' | 'wipeOut' | 'shrink' | 'zoomOut' | 'motionPath';
export type AnimTrigger = 'onClick' | 'withPrev' | 'afterPrev';
export type AnimClass = 'entrance' | 'emphasis' | 'exit' | 'path';
export interface SlideAnimation {
    /** Target shape's cNvPr id (<p:spTgt spid>) */
    spid: number;
    effect: AnimEffectKind;
    trigger: AnimTrigger;
    durationMs: number;
    delayMs: number;
    /**
     * Motion path (valid when effect='motionPath'): SVG subset M/L/C/Z,
     * coordinates 0..1 relative to slide width/height (same as OOXML animMotion's
     * relative path).
     */
    motionPath?: string;
    /** Per-paragraph animation: 0-based paragraph number (written as pgRg st/end); unset = whole shape */
    paragraph?: number;
}
/** Effect → class (entrance/emphasis/exit/motion path). */
export declare function animClassOf(effect: AnimEffectKind): AnimClass;
/** Extract the element's own <p:cNvPr id> from its raw bytes (the first one is the element itself; group children follow). */
export declare function elementSpid(el: SlideElement): number | null;
/** Default motionPath (straight line to the right, 1/4 of the slide width). */
export declare const DEFAULT_MOTION_PATH = "M 0 0 L 0.25 0";
export declare function buildTimingXml(anims: SlideAnimation[]): string;
/**
 * In-place patch of the bodySuffix's <p:timing> (schema order: after transition, before extLst).
 * With an existing timing, only the main sequence is rebuilt and unmodeled sibling
 * nodes are kept; empty anims removes the main sequence (the timing stays if other
 * nodes remain, and is removed only when fully empty). Returns the new bodySuffix.
 */
export declare function patchSlideTimingXml(bodySuffix: string, anims: SlideAnimation[]): string;
/**
 * Read the bodySuffix's animation list (for UI echo + slideshow).
 * Parses every effect cTn carrying presetClass; delay is derived back to the user
 * delay per the write convention (withPrev minus previous start / afterPrev minus
 * previous end).
 */
export declare function readSlideTimingXml(bodySuffix: string): SlideAnimation[];
/**
 * Incremental <p:timing> patch: touches only the affected effect nodes; unmodeled
 * sibling nodes (interactive trigger sequences, text-level animations, media
 * timelines, ...) keep their original bytes. Two supported shapes:
 *   A. Pure append (old list is a prefix of the new one, and the first added item
 *      is onClick) → new click groups are inserted at the end of the mainSeq;
 *   B. Tail single-item edit (same length, only one item changed, trigger/target
 *      unchanged, and no chained dependency after it) → replace that effect's
 *      <p:par> wholesale.
 * Everything else (delete/reorder/trigger change) returns null and the caller
 * falls back to a full rebuild.
 */
export declare function patchSlideTimingIncrementalXml(bodySuffix: string, anims: SlideAnimation[]): string | null;
/**
 * Set the slide's full animation list. Tries the incremental patch first (append /
 * tail single-item edit, keeping unmodeled timing nodes); when inapplicable, falls
 * back to the overwrite-style full rebuild (writes bodySuffix, persisted with the
 * whole-slide rebuild on save).
 */
export declare function setSlideAnimations(slide: Slide, anims: SlideAnimation[]): void;
/** Read the current slide's animation list. */
export declare function getSlideAnimations(slide: Slide): SlideAnimation[];
